input.script:
(() => {
  const rows = [...document.querySelectorAll('.picker-recent-row, [class*="picker-recent"]')];
  return {
    url: location.href,
    hasPicker: !!document.querySelector('[class*="picker"]'),
    rowCount: rows.length,
    bodyStart: document.body.innerText.slice(0, 400)
  };
})()

(() => {
  window.__ann = "pending";
  window.__TAURI_INTERNALS__.invoke("picker_announce_actions")
    .then(r => { window.__ann = JSON.stringify(r); })
    .catch(e => { window.__ann = "ERR " + String(e); });
  return "fired";
})()

(() => {
  const rows = [...document.querySelectorAll('[class*="picker-recent-row"]')];
  const out = rows.slice(0, 8).map(r => {
    const name = r.querySelector('[class*="picker-recent-name"]')?.textContent || "?";
    const ann  = r.querySelector('[class*="announce"]')?.textContent || null;
    const door = r.querySelectorAll('[class*="no-fire"], [class*="nofire"]').length;
    return { name, ann, door };
  });
  return { total: rows.length, rows: out };
})()

(() => {
  const rows = [...document.querySelectorAll('[class*="picker-recent-row"]')];
  const target = rows.find(r => (r.querySelector('[class*="picker-recent-name"]')?.textContent||"").trim() === "scratch-b");
  if (!target) return "row not found";
  const openBtn = target.querySelector('button[class*="picker-recent-open"], button');
  if (!openBtn) return "open button not found";
  openBtn.click();
  return "clicked open area of scratch-b: " + openBtn.className;
})()

(() => {
  // Read workspaces[] from the React fiber — NEVER map panes by DOM order (last session's error).
  const host = document.querySelector('[class*="xterm"]') || document.body;
  let f = host;
  const keys = Object.keys(host).filter(k => k.startsWith('__reactFiber'));
  let node = keys.length ? host[keys[0]] : null;
  let found = null;
  let depth = 0;
  while (node && depth < 200) {
    let hook = node.memoizedState;
    let hi = 0;
    while (hook && hi < 40) {
      const s = hook.memoizedState;
      if (s && typeof s === 'object' && Array.isArray(s.workspaces)) { found = s.workspaces; break; }
      hook = hook.next; hi++;
    }
    if (found) break;
    node = node.return; depth++;
  }
  return {
    depth,
    workspaces: found ? found.map(w => ({
      id: w.id, path: w.project_path, cc: w.cc_session_id,
      pending: w.pending_action ? JSON.stringify(w.pending_action) : null
    })) : null
  };
})()

(() => {
  window.__seed = { sawMarker: false, maxLen: 0, samples: 0, firstSeenAt: null };
  const t0 = Date.now();
  const pane = document.querySelector('[class*="xterm-screen"], [class*="xterm"]');
  window.__seedTimer = setInterval(() => {
    const p = document.querySelector('[class*="xterm-screen"], [class*="xterm"]');
    if (!p) return;
    const txt = p.innerText || "";
    window.__seed.samples++;
    if (txt.length > window.__seed.maxLen) window.__seed.maxLen = txt.length;
    if (!window.__seed.sawMarker && txt.includes("ARM1-SEED-7734")) {
      window.__seed.sawMarker = true;
      window.__seed.firstSeenAt = Date.now() - t0;
    }
  }, 500);
  return "sampler installed; pane present: " + !!pane;
})()

(() => {
  const p = document.querySelector('[class*="xterm-screen"], [class*="xterm"]');
  const txt = p ? (p.innerText || "") : "(no pane)";
  return {
    sampler: window.__seed,
    paneLen: txt.length,
    paneTail: txt.slice(-900)
  };
})()

