(() => {
  const panes = [...document.querySelectorAll('[data-session-id]')];
  return panes.map(p => {
    const rect = p.getBoundingClientRect();
    const rEl = p.querySelector('.xterm-rows');
    const ne = rEl ? [...rEl.children].filter(r=>(r.innerText||"").trim()).length : 0;
    // walk up for a display:none ancestor
    let anc = p, hidden = null, depth=0;
    while (anc && depth < 12) {
