(() => {
  const all = [...document.querySelectorAll('.xterm')];
  return all.map(t => {
    const rect = t.getBoundingClientRect();
    const rEl = t.querySelector('.xterm-rows');
    const rows = rEl ? [...rEl.children].map(r=>r.innerText||"") : [];
    const ne = rows.filter(r=>r.trim());
    let anc = t, hidden=null, d=0, cls=[];
    while (anc && d<10) { cls.push(anc.className?.toString().slice(0,60)); if (getComputedStyle(anc).display==='none' && !hidden) hidden=anc.className; anc=anc.parentElement; d++; }
    return { w:Math.round(rect.width), h:Math.round(rect.height), nonEmpty: ne.length, sample: ne.slice(0,6), hidden, ancestry: cls.slice(0,5) };
  });
})()

(() => {
  const ccPanes = [...document.querySelectorAll('.xterm')].filter(t => t.closest('.workspace-left'));
  return ccPanes.map((t, i) => {
    const rEl = t.querySelector('.xterm-rows');
    const rows = rEl ? [...rEl.children] : [];
    return {
      idx: i,
      rowCount: rows.length,
      // textContent, not innerText (innerText is layout-sensitive)
      textLen: rows.map(r => (r.textContent||"").length).reduce((a,b)=>a+b,0),
      firstRowsText: rows.slice(0,8).map(r => (r.textContent||"").trim()).filter(Boolean),
      anyText: rows.map(r=>r.textContent||"").join("").trim().slice(0,300)
    };
  });
})()

(() => {
  // Ask the app's own terminal for its buffer via the xterm instance if reachable through fiber props.
  const pane = [...document.querySelectorAll('.xterm-pane')].find(p => p.closest('.workspace-left'));
  const k = Object.keys(pane||{}).find(x => x.startsWith('__reactFiber'));
  let node = k ? pane[k] : null, term = null, d = 0;
  while (node && d < 40) {
    const st = node.stateNode;
    if (st && st.buffer && st.buffer.active) { term = st; break; }
    // hooks may hold the Terminal in a ref
    let h = node.memoizedState, i = 0;
    while (h && i < 40) {
      const s = h.memoizedState;
      if (s && s.current && s.current.buffer && s.current.buffer.active) { term = s.current; break; }
      h = h.next; i++;
    }
    if (term) break;
    node = node.return; d++;
  }
  if (!term) return { found: false, depth: d };
  const b = term.buffer.active;
  const lines = [];
  for (let y = 0; y < Math.min(b.length, 60); y++) {
    const ln = b.getLine(y);
    if (ln) { const s = ln.translateToString(true); if (s.trim()) lines.push(s); }
  }
  return { found: true, cols: term.cols, rows: term.rows, bufLen: b.length, lines: lines.slice(0,30) };
})()

(() => {
  const panes = [...document.querySelectorAll('.xterm-pane')].filter(p => p.closest('.workspace-left'));
  const readTerm = (pane) => {
    const k = Object.keys(pane).find(x => x.startsWith('__reactFiber'));
    let node = k ? pane[k] : null, term = null, d = 0;
    while (node && d < 40) {
      let h = node.memoizedState, i = 0;
      while (h && i < 40) {
        const s = h.memoizedState;
        if (s && s.current && s.current.buffer && s.current.buffer.active) { term = s.current; break; }
        h = h.next; i++;
      }
      if (term) break;
      node = node.return; d++;
    }
    if (!term) return null;
    const b = term.buffer.active;
    const out = [];
    for (let y=0; y<b.length; y++) { const ln=b.getLine(y); if(ln){const s=ln.translateToString(true); if(s.trim()) out.push(s);} }
    return out;
  };
  return panes.map((p,i) => {
    const lines = readTerm(p);
    const joined = (lines||[]).join("\n");
    return {
      idx: i,
      lineCount: lines ? lines.length : null,
      trustPrompt: /trust this folder/i.test(joined),
      hasSeed: joined.includes("ARM1-SEED-7734"),
      hasWombat: /wombat/i.test(joined),
      hasRestore: joined.includes("/session-restore"),
      head: (lines||[]).slice(0,4)
    };
  });
})()

