(() => {
  // Does a click on ⏵ reach the open button? Instrument the row's button before clicking.
  const rows = [...document.querySelectorAll('[class*="picker-recent-row"]')];
  const t = rows.find(r => (r.querySelector('.picker-recent-name')?.textContent||"").trim() === "scratch-b");
  const openBtn = t.querySelector('button.picker-recent');
  const nofire = t.querySelector('.picker-recent-nofire');
  window.__clicks = { openBtn: 0, nofire: 0 };
  openBtn.addEventListener('click', () => { window.__clicks.openBtn++; }, true); // capture phase
  nofire.addEventListener('click', () => { window.__clicks.nofire++; }, true);
  // also check hit-testing: is ⏵ the topmost element at its own centre?
  const r = nofire.getBoundingClientRect();
  const cx = r.left + r.width/2, cy = r.top + r.height/2;
  const top = document.elementFromPoint(cx, cy);
  return {
    nofireRect: {x:Math.round(r.x), y:Math.round(r.y), w:Math.round(r.width), h:Math.round(r.height)},
    topmostAtCentre: top ? (top.className || top.tagName) : null,
    hitTestsToSelf: top === nofire || nofire.contains(top),
    listenersInstalled: true
  };
})()

(() => {
  const rows = [...document.querySelectorAll('[class*="picker-recent-row"]')];
  const t = rows.find(r => (r.querySelector('.picker-recent-name')?.textContent||"").trim() === "scratch-b");
  const nofire = t.querySelector('.picker-recent-nofire');
  const r = nofire.getBoundingClientRect();
  const cx = r.left + r.width/2, cy = r.top + r.height/2;
  // Dispatch a REAL pointer-accurate click at the ⏵'s centre, via elementFromPoint —
  // this exercises bubbling/stopPropagation exactly as a user press would.
  const target = document.elementFromPoint(cx, cy);
  const opts = { bubbles: true, cancelable: true, clientX: cx, clientY: cy, view: window };
  target.dispatchEvent(new PointerEvent('pointerdown', opts));
  target.dispatchEvent(new MouseEvent('mousedown', opts));
  target.dispatchEvent(new PointerEvent('pointerup', opts));
  target.dispatchEvent(new MouseEvent('mouseup', opts));
  target.dispatchEvent(new MouseEvent('click', opts));
  return { dispatchedAt: {cx:Math.round(cx), cy:Math.round(cy)}, target: target.className, clicks: window.__clicks };
})()

