// M12 WP3 — the auto-resume decision function.
//
// ═══════════════════════════════════════════════════════════════════════════════
// TWO SIGNALS → ONE ACTION, AND THE PRECEDENCE REVERSES THE ROADMAP
//
//   1. the unclean-exit flag  (M12 WP2, `session-state.json`)  → continue the conversation
//   2. `workflow-system/state/.session.md` present             → `/session-restore`
//   3. neither                                                 → nothing fires
//
// ⚠️ THE UNCLEAN FLAG WINS. This **reverses** the roadmap's *"both present → prefer
// `/session-resume`, workflow context is richer."* Operator's reason (2026-08-03): the
// flag is an **explicit user signal** (they closed the workspace with the ⏸, or the
// machine died mid-flight); `.session.md` is **semi-automated** — written by a skill. An
// explicit statement of intent outranks a file a tool wrote.
//
// A future reader WILL find the roadmap's opposite ordering and be tempted to "fix" this
// back. `predictAction.test.ts` mutation-proves the direction: inverting the two branches
// fails a test that says exactly why.
//
// ═══════════════════════════════════════════════════════════════════════════════
// ⚠️ WHY THE RETURN VALUE IS A KIND AND NOT A COMMAND STRING (Phase 1's verdict)
//
// The plan originally specified `→ "resume" | "restore" | null`. Phase 1's live probe
// killed that shape, and the reason is not cosmetic — **the two arms are different KINDS
// of action, consumed at different moments by different code:**
//
//   arm 1  spawn argv `--continue`   — chosen BEFORE the process exists, passed in argv
//   arm 2  inject `/session-restore` — typed INTO the process ~1500 ms after it starts
//
// A bare `/resume` slash command does **not** resume anything: it opens an interactive
// modal session picker ("Resume session", "1 of 17", a search box, "Esc to cancel"), which
// would strand the user in a keyboard modal on every unclean re-open — worse than firing
// nothing. There is no `/continue` slash command either (Claude Code's autocomplete lists
// one entry, `/resume (continue)`). The only non-interactive continue is the CLI flag
// `-c/--continue`, verified live to restore the prior conversation and land at a ready
// prompt with no picker.
//
// So a single string return would force every caller to re-derive "…and is this one an
// argv flag or something I type?" — the exact re-interpretation that invites one caller to
// get it wrong. The kind is part of the decision, so the decision returns it.
//
// Evidence + the full run tables: the WIP's `## Probe verdict (Phase 1)`.

/** The two signals, as read at picker-open time (or re-derived at click time). */
export type AutoResumeSignals = {
  /** The M12 WP2 unclean-exit flag for this project. */
  uncleanFlag: boolean;
  /** Whether `workflow-system/state/.session.md` exists in the project. */
  sessionMdPresent: boolean;
};

/**
 * Continue the most recent conversation by passing a flag in Claude Code's argv.
 *
 * Requires NO injection and NO settle delay — the flag is present at `execvp` time, so
 * Claude Code resumes as part of its own boot. This is why Phase 1's verdict made arm 1
 * the *safe* arm: the milestone's riskiest mechanism (composing input on the app's own
 * initiative) now covers one arm instead of two.
 */
export type ArgvAction = {
  kind: "argv";
  /** The CLI flag to add to the spawn argv. */
  flag: "--continue";
};

/**
 * Type a slash command into the running TUI.
 *
 * ⚠️ Timing-sensitive: measured NOT-EXECUTED 5/5 at spawn time and unreliable at 350 ms
 * (1/5 then 0/5 across two independent samples). See {@link INJECT_SETTLE_MS}.
 */
export type InjectAction = {
  kind: "inject";
  /** The command to type. ⚠️ `/session-resume` does not exist — renamed at WP5/M9. */
  command: "/session-restore";
};

/** What to do when a workspace opens. `null` = nothing fires. */
export type AutoResumeAction = ArgvAction | InjectAction | null;

/**
 * How long to wait after spawn before injecting, in milliseconds.
 *
 * ⚠️ **Do not lower this without re-running `tooling/autofire-timing/probe.sh`.** It is a
 * deliberate ~4× margin over a measured cliff, not a round number:
 *
 * | delay | result (5 cold spawns each) |
 * |-------|------------------------------|
 * | 0 ms (spawn/`cc_ready`) | NOT-EXECUTED 5/5 |
 * | 250 / 300 ms | NOT-EXECUTED 5/5 |
 * | **350 ms** | **1/5, then 0/5 — unreliable** |
 * | 400–500 ms | EXECUTED 5/5 |
 * | **1500 ms** | **EXECUTED 10/10, twice; 5/5 under 4-core load** |
 *
 * The 350 ms row is the reason for the margin: it is the "works warm, fails cold" mode,
 * sitting 50 ms below a delay that reads as perfectly reliable. And the threshold is
 * environment-dependent — this was measured on one machine with a warm binary, so a
 * slower machine moves it.
 */
export const INJECT_SETTLE_MS = 1500;

/**
 * Decide what a workspace open should fire, from the two signals.
 *
 * Pure and total: every input combination maps to exactly one outcome, and there is no IO
 * here so tests drive the real decision rather than a replica.
 *
 * ⚠️ **This is the ONLY home for the precedence rule.** The `picker_announce_actions`
 * batch command returns the *resolved* action, in which both inputs are already collapsed
 * into one value — a resolved payload cannot be mutation-tested for precedence, because
 * you can no longer vary the inputs independently. WP1's Verdict (b) calls this out
 * explicitly: the command *calls* this function; the tests drive this function.
 */
export function predictAction(signals: AutoResumeSignals): AutoResumeAction {
  // ⚠️ ORDER IS THE FEATURE. The flag is checked FIRST so that when both signals are
  // present the explicit one wins. Swapping these two branches is the "fix" the roadmap
  // invites; `precedence_the_unclean_flag_wins_when_both_signals_are_present` fails if
  // you do.
  if (signals.uncleanFlag) {
    return { kind: "argv", flag: "--continue" };
  }
  if (signals.sessionMdPresent) {
    return { kind: "inject", command: "/session-restore" };
  }
  // Neither signal: fire NOTHING. `/session-start` is never auto-fired — it is rare
  // (2.7% of cold opens in the log analysis) and expensive when wrong, so it gets an
  // explicit button (Phase 5) instead of a prediction.
  return null;
}

/**
 * The literal command text a picker row announces for `action`, or `null` for no
 * announcement.
 *
 * Deliberately a **separate** function from {@link predictAction}: the label is what the
 * user reads, the action is what runs, and they are allowed to differ in form. Arm 1's
 * action is the argv flag `--continue`, but a row announcing `--continue` would be
 * meaningless to a reader — what they care about is *"this will pick up my last
 * conversation."* Announcing `/resume` would be worse than meaningless: it names a command
 * that opens a picker, which is precisely what this design avoids.
 */
export function announcementFor(action: AutoResumeAction): string | null {
  if (action === null) return null;
  switch (action.kind) {
    case "argv":
      return "continue";
    case "inject":
      return action.command;
  }
}

/**
 * Whether `action` needs a command typed into the PTY after spawn.
 *
 * Exists so a call site cannot answer this by string-matching the command text — the
 * question is about the action's *kind*, and the kind is authoritative.
 */
export function requiresInjection(action: AutoResumeAction): boolean {
  return action?.kind === "inject";
}

/**
 * The wire vocabulary `picker_announce_actions` returns, mirrored from Rust
 * (`src-tauri/src/announce/mod.rs` → `ACTION_CONTINUE` / `ACTION_RESTORE`).
 *
 * ⚠️ Deliberately NOT the command text and NOT the raw flag. `"continue"` rather than
 * `"resume"` because arm 1 is a spawn argv flag, and a payload naming `/resume` would
 * invite a caller to type it — which opens an interactive picker instead of resuming.
 */
export type AnnouncedAction = "continue" | "restore";

/** project path → announced action. An **absent key means no prediction**. */
export type AnnounceMap = Readonly<Record<string, AnnouncedAction>>;

/**
 * Turn one announced wire value into the action it denotes.
 *
 * This is the seam between the batch command and {@link predictAction}'s kinds: the command
 * resolves *which* arm (it has the two signals), and this maps that answer back onto the
 * same typed action the click path produces. Both sides therefore agree by construction
 * rather than by two call sites independently remembering what `"continue"` means.
 *
 * An unrecognized value yields `null` — a stale frontend paired with a newer backend
 * announces nothing rather than guessing, which fails toward "no auto-fire".
 */
export function actionFromAnnounced(
  announced: AnnouncedAction | undefined,
): AutoResumeAction {
  switch (announced) {
    case "continue":
      return { kind: "argv", flag: "--continue" };
    case "restore":
      return { kind: "inject", command: "/session-restore" };
    default:
      return null;
  }
}

/**
 * Extra argv Claude Code should be spawned with for `action`.
 *
 * Returns `[]` for the inject and null arms, so a spawn path can always concatenate the
 * result without branching. ⚠️ Keep this the ONLY place the flag string is produced — a
 * second literal `"--continue"` at a call site is a second source of truth.
 */
export function spawnArgvFor(action: AutoResumeAction): readonly string[] {
  return action?.kind === "argv" ? [action.flag] : [];
}

// M12 WP3 Phase 3 — the picker row's announcement + two-door logic, as pure functions.
//
// Extracted rather than inlined in `ProjectPicker.tsx` because this repo has **no React
// component-render harness** (`@testing-library/react` is not a dependency —
// `SURFACE-2026-07-31-NO-REACT-COMPONENT-RENDER-HARNESS`, still open). So anything asserted
// as a *value* must live in a module a test can import; anything left in JSX can only be
// checked by a source-text guard or by driving the live app. That is the standing method
// (`[[extract-for-import-when-a-raw-guard-cant-express-the-property]]`).
//
// ═══════════════════════════════════════════════════════════════════════════════
// ⚠️ ONE CONDITIONAL GOVERNS BOTH THE LABEL AND THE BUTTON
//
// The announcement and the `⏵` no-fire door appear **exactly together**, because with no
// predicted action both doors are identical and `⏵` would be a control that provably does
// nothing. [`rowAffordances`] returns both from a single decision so the component cannot
// render one without the other — the alternative (two independent `action !== null` checks
// in JSX) is two places to forget.
//
// ═══════════════════════════════════════════════════════════════════════════════
// ⚠️ THE WORKFLOW GATE APPLIES PER ARM, NOT TO THE WHOLE ROW (2026-08-05)
//
// Until Phase 3.5, `rowAffordances` returned SILENT whenever the gate was off. That was
// correct-as-built and is now WRONG — see [`armAvailable`] for the rule and its reason.
// In short: the `--continue` arm reads Claudesk's own store and fires a stock Claude Code
// CLI flag, so it serves every CC user and is UNGATED; the `/session-restore` arm promises
// something about `workflow-system/` files and stays GATED.
//
// The pairing above is unaffected: within whichever arm survives, the label and the door
// still appear together or not at all.

import {
  actionFromAnnounced,
  announcementFor,
  type AnnounceMap,
  type AnnouncedAction,
  type AutoResumeAction,
} from "../../state/predictAction";
import type { useWorkflowFeaturesEnabled } from "../../state/useWorkflowFeaturesEnabled";

/**
 * The workflow-features gate's value type, referenced from the seam itself.
 *
 * ⚠️ **This alias is load-bearing and must stay in executable source.** The OFF-invariant
 * guard's chord arm scans modules for a reference to the gate seam and **strips comments
 * before matching** — a comment-only mention was *measured* not to satisfy it during M11.
 * Copying `panelHost.ts:43`'s exact pattern is what makes this module's gate-dependency
 * structural rather than documentary.
 */
type WorkflowGateValue = ReturnType<typeof useWorkflowFeaturesEnabled>;

/** What one picker row should render for the auto-resume feature. */
export interface RowAffordances {
  /** The command text to display next to the project name, or `null` for no announcement. */
  announcement: string | null;
  /** Whether to render the `⏵` open-without-firing button. */
  showNoFireDoor: boolean;
  /** The action a normal row click should fire, or `null` to open plainly. */
  action: AutoResumeAction;
}

/** Nothing announced, no second door, no action. The gate-OFF and no-signal answer. */
const SILENT: RowAffordances = {
  announcement: null,
  showNoFireDoor: false,
  action: null,
};

/**
 * Whether an action's arm is available given the workflow-features gate.
 *
 * ⚠️ **THE GATE IS PER-ARM, NOT PER-FEATURE** (operator decision 2026-08-05). Mirrors
 * `arm_available` in `src-tauri/src/announce/mod.rs`; the two must agree.
 *
 * | arm | reads | gated? |
 * |---|---|---|
 * | `{kind:"argv"}` — `--continue` | `session-state.json` (Claudesk's own store) | **NO** |
 * | `{kind:"inject"}` — `/session-restore` | `workflow-system/state/.session.md` | **YES** |
 *
 * The discriminator is **applicability**, which is what
 * `gate-substrate-dependent-feature-class-behind-default-off-opt-in` actually keys on —
 * never audience size. The unclean-exit flag is written by Claudesk's own workspace
 * lifecycle (M12 WP2) and `--continue` is a stock Claude Code CLI flag: nothing in that arm
 * touches `~/.claude/skills/` or `workflow-system/`, so it serves **every** Claude Code
 * user and gating it was a mis-application of the prior. The `.session.md` arm promises
 * something about files a non-workflow user does not have, which is what the gate is for.
 *
 * ⚠️ Branches on the action's **`kind`**, never on its label or the wire string. The kind is
 * the authority (`predictAction.ts`), and this is the third consumer that must not
 * re-derive the distinction from text.
 */
function armAvailable(
  action: NonNullable<AutoResumeAction>,
  enabled: WorkflowGateValue,
): boolean {
  // Exhaustive on `kind`: adding a third arm makes this a type error rather than silently
  // inheriting whichever default a wildcard happened to pick.
  switch (action.kind) {
    case "argv":
      return true;
    case "inject":
      return enabled;
  }
}

/**
 * Decide what one row renders, from the batched announce map.
 *
 * ⚠️ **`enabled` no longer collapses the whole row.** Before 2026-08-05 this returned
 * {@link SILENT} unconditionally when the gate was off; that was correct-as-built and is now
 * wrong. The gate applies **per arm** — see {@link armAvailable}. A gated-out arm still
 * collapses completely (no announcement, no `⏵`, no action), honoring the seam contract
 * *a gated surface must not exist when off*; an ungated arm renders regardless.
 *
 * Belt-and-braces with the backend, which applies the same split server-side: an OFF build's
 * map already omits the gated arm, so this check means the row stays correct even with a
 * stale map in hand — two independent reasons, matching how M10.9 pairs the server-side gate
 * read with the frontend seam.
 */
export function rowAffordances(
  projectPath: string,
  announce: AnnounceMap,
  enabled: WorkflowGateValue,
): RowAffordances {
  const action = actionFromAnnounced(
    announce[projectPath] as AnnouncedAction | undefined,
  );
  if (action === null) return SILENT;
  if (!armAvailable(action, enabled)) return SILENT;
  return {
    announcement: announcementFor(action),
    // ⚠️ Deliberately derived from the SAME decision as the label above, not from a second
    // independent check. See the module header.
    showNoFireDoor: true,
    action,
  };
}

/**
 * Which door was used, and therefore whether to fire.
 *
 * A two-member vocabulary rather than a bare boolean, so the call site reads as an intent
 * ("the user took the no-fire door") instead of a polarity that has to be remembered
 * (`fire: false` vs `noFire: true` are the same fact spelled two ways, and one of them is
 * always the one you get wrong).
 */
export type OpenIntent = "fire" | "no-fire";

/**
 * The action to actually fire, given the door taken and the CURRENT signals.
 *
 * ⚠️ **`action` must be RE-DERIVED at click time, never read from the rendered label.**
 * WP1's Verdict (b) is explicit: *the announcement is a prediction, never the input to the
 * action.* `.session.md` can vanish while the picker is open (`/session-restore` deletes it
 * at its own step 7 — observed live during WP1's own probe phase), so a label can be stale.
 *
 * Because the decision that *acts* is computed fresh, the staleness window is
 * **display-only and self-correcting**: the worst case is a label that promised an action
 * and nothing firing — **never a wrong action**. Reading the label instead would convert a
 * harmless stale label into a genuinely wrong fire.
 *
 * This function is the enforcement point for that rule: it takes the freshly-derived action
 * and the door, and the `"no-fire"` door discards the action regardless of what it was.
 */
export function actionForIntent(
  action: AutoResumeAction,
  intent: OpenIntent,
): AutoResumeAction {
  return intent === "fire" ? action : null;
}

