  const panes = [...document.querySelectorAll('.xterm-pane')].filter(p => p.closest('.workspace-left'));
  const readTerm = (pane) => {
    const k = Object.keys(pane).find(x => x.startsWith('__reactFiber'));
    let node = k ? pane[k] : null, term = null, d = 0;
    while (node && d < 40) {
      let h = node.memoizedState, i = 0;
      while (h && i < 40) {
        const s = h.memoizedState;
        if (s && s.current && s.current.buffer && s.current.buffer.active) { term = s.current; break; }
        h = h.next; i++;
      }
      if (term) break;
      node = node.return; d++;
    }
    if (!term) return null;
    const b = term.buffer.active;
    const out = [];
    for (let y=0; y<b.length; y++) { const ln=b.getLine(y); if(ln){const s=ln.translateToString(true); if(s.trim()) out.push(s);} }
    return out;
  };
  return panes.map((p,i) => {
    const lines = readTerm(p) || [];
    const j = lines.join("\n");
    return { idx: i, lineCount: lines.length, booted: /Claude Code|Welcome/i.test(j), head: lines.slice(0,2) };
  });
})()

