1	// WP5 — Workspace: one project's pane. 50/50 horizontal split.
2	//
3	// Left half: the xterm.js terminal — a real PTY-backed CC session as of WP7.
4	// Right half: the RightPanelHost (WP5) — owns the Editor↔Diff(↔terminal) panels,
5	// the panel-select hotkeys (⌘⇧E/D/T), and the external-Sublime launch icon buttons
6	// (in the panel tab row, WP8).
7	// (Before WP5 the right half was an inline segmented toggle living in this file.)
8	//
9	// CRITICAL invariant (CLAUDE.md "All workspaces stay mounted"): this component
10	// is NEVER unmounted to switch the center stage. When not focused it stays mounted
11	// (xterm + PTY connection persist) but is pushed OFF-VIEWPORT (`left:-99999px`),
12	// NOT hidden with `display:none`. Two reasons, both load-bearing for M4 WP3's live
13	// filmstrip mirror (WP4 thumbnail-probe findings):
14	//   1. Off-viewport keeps the element laid out with real dimensions, so xterm's
15	//      FitAddon `fit()` still works (`display:none` → zero dims → `fit()` throws).
16	//   2. Off-viewport lets xterm's IntersectionObserver PAUSE the background
17	//      renderer for free (~5ms/frame saved) while the buffer still updates via
18	//      `write()` — so the filmstrip can read a current `serializeAsHTML()` snapshot
19	//      from the paused-renderer buffer (WP3 P3). `display:none` would also pause
20	//      rendering but breaks fit + can't be serialized into a sized tile.
21	// The `visible` prop drives that toggle, and is forwarded to RightPanelHost to gate
22	// panel liveness + the capture-phase hotkey (only the focused workspace's host reacts).
23	
24	import { useEffect, useRef, useState } from "react";
25	import { invoke } from "@tauri-apps/api/core";
26	import type { Workspace as WorkspaceModel } from "../../state/workspace";
27	import { XtermPane, type XtermPaneHandle } from "./XtermPane";
28	import { RightPanelHost } from "./RightPanelHost";
29	import { WorkspaceStatusIndicator } from "./WorkspaceStatusIndicator";
30	import type { WireWorkspaceState } from "../../state/workspaceStatus";
31	import { deriveFocusHalf, type FocusHalf } from "./focusHalf";
32	import { deriveRightSurface } from "./rightSurface";
33	import {
34	  loadSplitState,
35	  saveSplitState,
36	  gridColumnsFor,
37	  cycleRatio,
38	  toggleCollapse,
39	  type SplitState,
40	} from "./splitWidth";
41	import {
42	  loadTerminalFontSize,
43	  saveTerminalFontSize,
44	  nextTerminalFontSize,
45	  terminalZoomForChord,
46	  DEFAULT_TERMINAL_FONT_PX,
47	} from "./terminalFontZoom";
48	// M12 WP3 Phase 5 — the third arm. Both surfaces are GATED (a workflow skill + a statement
49	// about `workflow-system/` state), unlike Phase 3.5's ungated `--continue` announcement.
50	import { useWorkflowFeaturesEnabled } from "../../state/useWorkflowFeaturesEnabled";
51	import { predictAction } from "../../state/predictAction";
52	import { slashCommandPayload } from "./autoResumeFire";
53	import {
54	  nextOpenIndicator,
55	  SESSION_START_COMMAND,
56	  showSessionStartButton,
57	} from "./sessionStartButton";
58	
59	interface WorkspaceProps {
60	  workspace: WorkspaceModel;
61	  visible: boolean;
62	  /** Store the backend CC session id once cc_spawn resolves (WP7). */
63	  onSessionId?: (workspaceId: string, ccSessionId: string) => void;
64	  /** QoL-WP1 — register this workspace's unsaved-doc probe with App's close guard. */
65	  registerDirtyProbe?: (
66	    workspaceId: string,
67	    probe: (() => number) | null,
68	  ) => void;
69	  /**
70	   * Live CC state from the `workspace-status` hook channel (M3 WP6). Defaults to
71	   * `"unknown"` — the honest no-data state before any hook event arrives. Phase 2
72	   * feeds the live value from the app-level subscription.
73	   */
74	  statusState?: WireWorkspaceState;
75	  /** Last prompt/message snippet for the indicator tooltip (M3 WP6). */
76	  statusSnippet?: string;
77	}
78	
79	export function Workspace({
80	  workspace,
81	  visible,
82	  onSessionId,
83	  registerDirtyProbe,
84	  statusState = "unknown",
85	  statusSnippet,
86	}: WorkspaceProps) {
87	  // M4 WP4b — which half (left CC terminal / right panel) holds keyboard focus, so the
88	  // CSS can paint a #6ea8ff accent on it. Capture-phase focusin/focusout on this
89	  // workspace's root keeps the read scoped to THIS workspace (no document-level
90	  // listener that every workspace would re-handle). Only the visible/center-stage
91	  // workspace indicates: backgrounds are off-viewport + unfocusable, and clearing to
92	  // "none" on hide prevents a stale accent if a workspace is demoted while focused.
93	  const rootRef = useRef<HTMLDivElement>(null);
94	  const [focusHalf, setFocusHalf] = useState<FocusHalf>("none");
95	
96	  // ── M12 WP3 Phase 5 — the third arm ──────────────────────────────────────────────
97	  //
98	  // The gate seam. Read the HOOK, never the raw command or the one-shot wrapper: a one-shot
99	  // read never re-syncs on the broadcast, which is a defect that actually shipped in M10.9 WP3.
100	  const workflowEnabled = useWorkflowFeaturesEnabled();
101	  // What this workspace WOULD fire if reopened now. Re-read on every `visible` edge rather than
102	  // once on mount, because the whole point is to reflect a flag the ⏸ may have set *since* —
103	  // and workspaces stay mounted forever (the standing invariant), so a mount-only read would go
104	  // stale for the entire life of the app.
105	  const [nextOpen, setNextOpen] = useState<string | null>(null);
106	  useEffect(() => {
107	    if (!workflowEnabled || !visible) {
108	      // Gate off → the surface must not exist at all (the M10.9 seam contract), and a hidden
109	      // workspace has nothing to show. Clearing rather than freezing avoids a stale label
110	      // reappearing on the next promote.
111	      setNextOpen(null);
112	      return;
113	    }
114	    let cancelled = false;
115	    // Reuses the picker's batched command — one call returning every project's resolved action,
116	    // so this adds no per-workspace IPC shape. ⚠️ `.catch` is mandatory: an unhandled Tauri
117	    // rejection vanishes silently (the WP6 picker MAJOR), and this surface failing quietly is
118	    // exactly the write-only problem it exists to fix.
119	    invoke<Record<string, "continue" | "restore">>("picker_announce_actions")
120	      .then((map) => {
121	        if (cancelled) return;
122	        const announced = map[workspace.project_path];
123	        // ⚠️ Derived from the SIGNALS via the real predictor, not from the announced string —
124	        // the same rule the click path follows. A label is a prediction, never an input.
125	        setNextOpen(
126	          nextOpenIndicator({
127	            workflowEnabled: true,
128	            action: predictAction({
129	              uncleanFlag: announced === "continue",
130	              sessionMdPresent: announced === "restore",
