11	// QoL-WP3 — auto-focus the LEFT CC terminal when a workspace is promoted to center stage.
12	//
13	// The failure modes these tests exist to prevent:
14	//  1. The imperative focus handle is dropped from XtermPane → Workspace can no longer
15	//     focus the pane on promote (the feature silently no-ops).
16	//  2. The focus effect stops keying on `visible` (e.g. someone refactors it to fire
17	//     unconditionally, or removes the edge), so background workspaces steal focus or
18	//     promotion stops focusing.
19	//  3. Someone adds a PTY write on focus (cc_input / a stray \r\n inside the focus path),
20	//     re-introducing the WP4 spurious-prompt bug class on the LEFT pane.
21	// All three are wiring invariants not observable in jsdom (xterm needs a real DOM), so
22	// they're pinned structurally rather than relying on a human noticing the regression.
23	
24	describe("XtermPane exposes an imperative focus handle (QoL-WP3 P1.1)", () => {
25	  it("is a forwardRef component", () => {
26	    expect(xtermPaneSource).toMatch(/forwardRef<\s*XtermPaneHandle/);
27	  });
28	
29	  it("exports the XtermPaneHandle type with a focus() method", () => {
30	    expect(xtermPaneSource).toMatch(/export interface XtermPaneHandle/);
31	    expect(xtermPaneSource).toMatch(/focus\(\)\s*:\s*void/);
32	  });
33	
34	  it("wires the handle's focus() to term.focus() via useImperativeHandle", () => {
35	    expect(xtermPaneSource).toMatch(/useImperativeHandle/);
36	    expect(xtermPaneSource).toMatch(
37	      /focus:\s*\(\)\s*=>\s*termRef\.current\?\.focus\(\)/,
38	    );
39	  });
40	});
