42	/**
43	 * The focus effect's source text — the region the WP4 spurious-prompt guard actually governs.
44	 *
45	 * Anchored on `if (!visible) return;`, the effect's own early-return guard (which a sibling test
46	 * asserts independently), and terminated at the effect's closing `}, [visible]);`. Anchoring on
47	 * content rather than on a line number or an ordinal `useEffect` occurrence matters: `Workspace.tsx`
48	 * has several effects and Phase 5 added another, so "the Nth useEffect" would silently retarget.
49	 *
50	 * ⚠️ Throws rather than returning `""` when the anchors are gone. A slice that quietly yields an
51	 * empty string makes `not.toMatch(...)` pass vacuously — the positional-`?raw`-slicing hole this
52	 * repo has hit three times (`SURFACE-2026-07-28-QUALITY-WP2-RAW-GUARDS-STILL-LOAD-BEARING`,
53	 * `SURFACE-2026-07-29-CFG-TEST-SPLIT-BLINDS-SOURCE-GUARDS`).
54	 */
55	function extractFocusEffect(source: string): string {
56	  const start = source.indexOf("if (!visible) return;");
57	  if (start === -1) {
58	    throw new Error(
59	      "could not locate the focus effect's `if (!visible) return;` anchor in Workspace.tsx. " +
60	        "If the effect was reshaped, update this extractor DELIBERATELY — it is what scopes the " +
61	        "WP4 spurious-prompt guard to the focus path.",
62	    );
63	  }
64	  const end = source.indexOf("}, [visible]);", start);
65	  if (end === -1) {
66	    throw new Error(
67	      "found the focus effect's start but not its `}, [visible]);` terminator in Workspace.tsx.",
68	    );
69	  }
70	  return source.slice(start, end);
71	}
