input.script:
(() => {
  const el = document.querySelector('.picker-recent-nofire');
  if (!el) return { err: "no ⊘ control rendered", rows: document.querySelectorAll('[class*="picker-recent-row"]').length };
  const r = el.getBoundingClientRect();
  const cs = getComputedStyle(el);
  // A missing glyph renders as .notdef (a box) — detectable by measuring the text width
  // against a known-present char in the same font/size.
  const probe = (ch) => {
    const s = document.createElement('span');
    s.style.cssText = `position:absolute;visibility:hidden;font:${cs.font};white-space:pre`;
    s.textContent = ch;
    document.body.appendChild(s);
    const w = s.getBoundingClientRect().width;
    s.remove();
    return Math.round(w * 100) / 100;
  };
  return {
    text: el.textContent.trim(),
    codePoint: "U+" + el.textContent.trim().codePointAt(0).toString(16).toUpperCase(),
    rect: { w: Math.round(r.width), h: Math.round(r.height) },
    fontSize: cs.fontSize,
    ariaLabel: el.getAttribute('aria-label'),
    title: el.getAttribute('title'),
    glyphWidths: { "⊘": probe("⊘"), "↻": probe("↻"), "known-A": probe("A") }
  };
})()

