(() => {
  // OUTCOME 2 (the ⏸ read-back, and the promote-edge re-read): the indicator must TRACK the
  // flag. Clean-close scratch-a via the filmstrip ×, which CLEARS the flag, then reopen and
  // confirm the label is gone. That is the discriminating test — a hardcoded label would
  // survive it.
  const tiles = [...document.querySelectorAll('.filmstrip-tile')];
  const t = tiles.find(x => (x.textContent||"").includes("scratch-a"));
  if (!t) return { err: "no tile", tiles: tiles.map(x=>(x.textContent||"").trim().slice(0,22)) };
  const xs = [...t.querySelectorAll('*')].filter(e => (e.textContent||"").trim() === "×");
  xs[xs.length-1].click();
  return "clean-closed scratch-a (× clears the flag)";
})()

(() => {
  const rows = [...document.querySelectorAll('[class*="picker-recent-row"]')];
  const t = rows.find(r => (r.querySelector('.picker-recent-name')?.textContent||"").trim() === "scratch-a");
  if (!t) { const add = [...document.querySelectorAll('button')].find(b => b.className === "filmstrip-add"); if (add) { add.click(); return "opened picker — rerun"; } return "stuck"; }
  t.querySelector('button.picker-recent').click();
  return "reopened scratch-a with a CLEARED flag";
})()

(() => {
  const ind = document.querySelector('[data-testid="workspace-header-nextopen"]');
  const btn = document.querySelector('[data-testid="workspace-session-start"]');
  return {
    step: "reopened; flag re-set by the spawn",
    indicator: ind ? ind.textContent.trim() : "ABSENT",
    button: btn ? "PRESENT" : "ABSENT",
    note: "label present is correct here — the spawn re-set the flag. The DISCRIMINATOR is the gate."
  };
})()

(() => {
  window.__g = "pending";
  window.__TAURI_INTERNALS__.invoke("workflow_set_features_enabled", { enabled: false })
    .then(() => { window.__g = "OFF"; }).catch(e => { window.__g = "ERR " + e; });
  return "fired gate-off";
})()

(() => {
  const ind = document.querySelector('[data-testid="workspace-header-nextopen"]');
  const btn = document.querySelector('[data-testid="workspace-session-start"]');
  const header = document.querySelector('[data-testid="workspace-header"]');
  return {
    gate: window.__g,
    indicatorInDOM: ind !== null,
    buttonInDOM: btn !== null,
    headerText: header ? header.innerText.replace(/\n/g, " | ") : null,
    note: "both must be ABSENT from the DOM — not hidden, not disabled (the M10.9 seam contract)"
  };
})()

(() => {
  window.__g2 = "pending";
  window.__TAURI_INTERNALS__.invoke("workflow_set_features_enabled", { enabled: true })
    .then(() => { window.__g2 = "ON"; }).catch(e => { window.__g2 = "ERR " + e; });
  return "fired";
})()

(() => {
  const ind = document.querySelector('[data-testid="workspace-header-nextopen"]');
  const btn = document.querySelector('[data-testid="workspace-session-start"]');
  return {
    gate: window.__g2,
    buttonInDOM: btn !== null,
    indicatorInDOM: ind !== null,
    indicatorText: ind ? ind.textContent.trim() : null,
    note: "the BUTTON should return immediately (pure gate); the INDICATOR needs its effect to re-fire"
  };
})()

(() => {
  window.__readCC = () => {
    const panes = [...document.querySelectorAll('.xterm-pane')].filter(p => p.closest('.workspace-left'));
    const out = [];
    for (const pane of panes) {
      const k = Object.keys(pane).find(x => x.startsWith('__reactFiber'));
      let node = k ? pane[k] : null, term = null, d = 0;
      while (node && d < 40) {
        let h = node.memoizedState, i = 0;
        while (h && i < 40) {
          const s = h.memoizedState;
          if (s && s.current && s.current.buffer && s.current.buffer.active) { term = s.current; break; }
          h = h.next; i++;
        }
        if (term) break;
        node = node.return; d++;
      }
      if (!term) continue;
      const b = term.buffer.active, lines = [];
      for (let y = 0; y < b.length; y++) { const ln = b.getLine(y); if (ln) { const t = ln.translateToString(true); if (t.trim()) lines.push(t); } }
      out.push(lines);
    }
    return out;
  };
  window.__ss = { ticks: 0, sawEcho: false, sawExecution: false, firstExecTick: null };
  window.__ssTimer = setInterval(() => {
    window.__ss.ticks++;
    for (const lines of window.__readCC()) {
      const j = lines.join("\n");
      if (j.includes("/session-start")) window.__ss.sawEcho = true;
      // EXECUTION-side evidence: the skill's own vocabulary — it classifies work and picks a
      // workflow. Text the echoed command cannot contain.
      if (/classif|which workflow|feature workflow|task workflow|drive mode|Stepping|Orchestrated|Autopilot|routed/i.test(j)) {
        if (!window.__ss.sawExecution) window.__ss.firstExecTick = window.__ss.ticks;
        window.__ss.sawExecution = true;
      }
    }
  }, 1000);
  const pre = window.__readCC()[0] || [];
  return { samplerArmed: true, paneLinesBefore: pre.length, hasSessionStartBefore: pre.join("\n").includes("/session-start") };
})()

(() => {
  const btn = document.querySelector('[data-testid="workspace-session-start"]');
  if (!btn) return "button absent";
  const r = btn.getBoundingClientRect();
  const top = document.elementFromPoint(r.left + r.width/2, r.top + r.height/2);
  const reachable = top === btn || btn.contains(top);
  btn.click();
  return { clicked: "/session-start button", reachableBeforeClick: reachable, atTick: window.__ss.ticks };
})()

(() => {
  const panes = window.__readCC();
  const lines = panes[0] || [];
  return {
    sampler: window.__ss,
    lineCount: lines.length,
    tail: lines.slice(-18)
  };
})()

(() => {
  clearInterval(window.__ssTimer);
  // OUTCOME 4 / the carried check: a BACKGROUNDED workspace must not show the indicator
  // (`visible` term). Open a second workspace so scratch-a is demoted, then read BOTH headers.
  const add = [...document.querySelectorAll('button')].find(b => b.className === "filmstrip-add");
  if (!add) return "no add btn";
  add.click();
  return "to picker — will open scratch-c so scratch-a becomes a background workspace";
})()

(() => {
  const rows = [...document.querySelectorAll('[class*="picker-recent-row"]')];
  const t = rows.find(r => (r.querySelector('.picker-recent-name')?.textContent||"").trim() === "scratch-c");
  if (!t) return "no scratch-c";
  t.querySelector('button.picker-recent').click();
  return "opened scratch-c → scratch-a is now backgrounded";
})()

(() => {
  // Pair headers to workspaces via the FIBER, never DOM order (this WP's instrument lesson).
  const host = document.querySelector('.workspace') || document.body;
  const k = Object.keys(host).find(x => x.startsWith('__reactFiber'));
  let node = k ? host[k] : null, found = null, d = 0;
  while (node && d < 300) {
    let h = node.memoizedState, i = 0;
    while (h && i < 60) {
      const s = h.memoizedState;
      if (s && typeof s === 'object' && Array.isArray(s.workspaces)) { found = s.workspaces; break; }
      h = h.next; i++;
    }
    if (found) break;
    node = node.return; d++;
  }
  const focusedId = (() => {
    let n = node, r = null;
    while (n && !r) { let h = n.memoizedState, i = 0;
      while (h && i < 60) { const s = h.memoizedState;
        if (s && typeof s === 'object' && 'focusedId' in s) { r = s.focusedId; break; } h = h.next; i++; }
      n = n.return; }
    return r;
  })();
  const roots = [...document.querySelectorAll('.workspace')];
  return {
    focusedId,
    perWorkspace: (found || []).map((w, i) => {
      const root = roots[i];
      const ind = root?.querySelector('[data-testid="workspace-header-nextopen"]');
      const btn = root?.querySelector('[data-testid="workspace-session-start"]');
      const offscreen = root ? Math.round(root.getBoundingClientRect().left) < -1000 : null;
      return {
        path: (w.project_path || "").split("/").pop(),
        isFocused: w.id === focusedId,
        offViewport: offscreen,
        indicator: ind ? ind.textContent.trim() : "ABSENT",
        button: btn ? "present" : "ABSENT",
      };
    }),
  };
})()

(() => {
  const tiles = [...document.querySelectorAll('.filmstrip-tile')];
  const t = tiles.find(x => (x.textContent||"").includes("scratch-a"));
  if (!t) return "no scratch-a tile";
  t.click();
  return "promoted scratch-a back to center stage";
})()

(() => {
  const roots = [...document.querySelectorAll('.workspace')];
  return roots.map((root, i) => {
    const ind = root.querySelector('[data-testid="workspace-header-nextopen"]');
    const name = root.querySelector('.workspace-header-name')?.textContent?.trim();
    return {
      name,
      offViewport: Math.round(root.getBoundingClientRect().left) < -1000,
      indicator: ind ? ind.textContent.trim() : "ABSENT"
    };
  });
})()

(() => {
  const tiles = [...document.querySelectorAll('.filmstrip-tile')];
  return tiles.map(t => ({
    text: (t.textContent||"").trim().slice(0,22),
    tag: t.tagName,
    cls: t.className,
    hasActive: t.className.includes("active")
  }));
})()

(() => {
  const tiles = [...document.querySelectorAll('.filmstrip-tile')];
  const t = tiles.find(x => (x.textContent||"").includes("scratch-a"));
  const r = t.getBoundingClientRect();
  // Aim at the tile's LEFT portion, away from the × in its corner.
  const cx = r.left + r.width * 0.3, cy = r.top + r.height * 0.5;
  const top = document.elementFromPoint(cx, cy);
  const opts = { bubbles: true, cancelable: true, clientX: cx, clientY: cy, view: window };
  top.dispatchEvent(new PointerEvent('pointerdown', opts));
  top.dispatchEvent(new MouseEvent('mousedown', opts));
  top.dispatchEvent(new PointerEvent('pointerup', opts));
  top.dispatchEvent(new MouseEvent('mouseup', opts));
  top.dispatchEvent(new MouseEvent('click', opts));
  return { dispatchedAt: {cx:Math.round(cx), cy:Math.round(cy)}, hitTarget: top.className };
})()

(() => {
  const roots = [...document.querySelectorAll('.workspace')];
  const tiles = [...document.querySelectorAll('.filmstrip-tile')].map(t => ({
    name: (t.textContent||"").trim().slice(0,12), active: t.className.includes("active") }));
  return {
    tiles,
    workspaces: roots.map(root => {
      const ind = root.querySelector('[data-testid="workspace-header-nextopen"]');
      return {
        name: root.querySelector('.workspace-header-name')?.textContent?.trim(),
        offViewport: Math.round(root.getBoundingClientRect().left) < -1000,
        indicator: ind ? ind.textContent.trim() : "ABSENT"
      };
    })
  };
})()

(() => {
  clearInterval(window.__ssTimer);
  const s = window.__ss;
  delete window.__ss; delete window.__ssTimer; delete window.__readCC; delete window.__g; delete window.__g2;
  return { cleaned: true, finalSampler: s };
})()
